changeSet.sql:
UPDATE modeling_model_spec_import_apply_attempt SET operation_type = 'APPLY' WHERE operation_type IS NULL;
UPDATE modeling_model_spec_import_apply_result SET applied_action = CASE status WHEN 'CREATED' THEN 'CREATE' WHEN 'UPDATED' THEN 'UPDATE' WHEN 'SKIPPED' THEN 'SKIP' ELSE NULL END, dependency_json = '[]'::jsonb WHERE applied_action IS NULL OR dependency_json IS NULL;
ALTER TABLE modeling_model_spec_import_apply_attempt ADD CONSTRAINT ck_model_spec_import_apply_operation CHECK ( (operation_type = 'APPLY' AND target_attempt_id IS NULL) OR ( operation_type = 'FORWARD_UNDO' AND retry_source_attempt_id IS NULL AND target_attempt_id IS NOT NULL AND target_attempt_id <> id ) );
ALTER TABLE modeling_model_spec_import_apply_result ADD CONSTRAINT ck_model_spec_import_result_applied_action CHECK (applied_action IS NULL OR applied_action IN ('CREATE', 'UPDATE', 'SKIP', 'CANCEL')), ADD CONSTRAINT ck_model_spec_import_result_dependency_json CHECK (jsonb_typeof(dependency_json) = 'array'), ADD CONSTRAINT ck_model_spec_import_result_checkpoint_all_or_none CHECK ( ( merge_checkpoint_json IS NULL AND accepted_external_checksum IS NULL AND accepted_implementation_revision IS NULL AND accepted_implementation_checksum IS NULL AND mapped_model_spec_revision IS NULL AND mapped_model_spec_etag IS NULL ) OR ( merge_checkpoint_json IS NOT NULL AND jsonb_typeof(merge_checkpoint_json) = 'object' AND project_key IS NOT NULL AND btrim(project_key) <> '' AND accepted_external_checksum ~ '^[0-9a-f]{64}$' AND accepted_implementation_revision > 0 AND accepted_implementation_checksum ~ '^[0-9a-f]{64}$' AND mapped_model_spec_revision > 0 AND mapped_model_spec_etag ~ '^[0-9a-f]{64}$' AND status IN ('CREATED', 'UPDATED', 'SKIPPED') ) ), ADD CONSTRAINT ck_model_spec_import_result_pre_pins CHECK ( pre_attempt_pins_json IS NULL OR ( jsonb_typeof(pre_attempt_pins_json) = 'object' AND (pre_attempt_pins_json ->> 'modelRevision')::int > 0 AND pre_attempt_pins_json ->> 'modelChecksum' ~ '^[0-9a-f]{64}$' AND (pre_attempt_pins_json ->> 'implementationRevision')::int > 0 AND pre_attempt_pins_json ->> 'implementationChecksum' ~ '^[0-9a-f]{64}$' ) );
CREATE INDEX idx_model_spec_import_result_checkpoint ON modeling_model_spec_import_apply_result ( project_key, dbt_unique_id, created_date DESC, id DESC ) WHERE merge_checkpoint_json IS NOT NULL;
CREATE INDEX idx_model_spec_import_forward_undo_target ON modeling_model_spec_import_apply_attempt (tenant_id, target_attempt_id, created_date DESC) WHERE operation_type = 'FORWARD_UNDO';

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_SPEC_IMPORT_RECONCILIATION_UNDO_FORWARD_ONLY: Recovery requires a new forward changeset';
END $$;
